          title: '灰野边上的草药先生',
          description: '你在帝国东部三姓城外的村镇长大，跟一位到处跑的草药婆学了一手辨药与治外伤的本事。你见过兽人的商队，也给他们治过伤，因此会说一点乌尔语里的数目与身体部位的说法，也因此被村里人说成「跟野人混的」。你的医术不算高明——你会接骨、会缝合、会退热、会判断哪些伤救不了——但你知道一件别人不知道的事：你师父留下来的药方里有三张，材料单上写着「取灰地生之盐晶」，而这种盐晶只在灰野的一个特定地方有，那里正是兽人每年放下一头牛的地方。你一直没敢去。你现在背着一个诊疗包走街串巷，收钱不多，但你知道很多人的身体状况，这件事在某些场合比钱值钱。',
          attributeBonus: { craft: 2, lore: 1 },
          resourceBonus: { health: 1, coin: 3 },
          startingItems: ['herb_kit', 'travel_cloak'],
