          title: '走出洞去的旧民',
          description: '你是旧民，四十一岁，身高五尺，皮肤白得发青，白天出门要眯着眼。你出生的那处火塘在三年前分成了两半，一半留下，一半走出洞去，你是走出去的那一半里活得比较久的几个之一。你现在能在地表走路、能忍受没有顶的地方（虽然睡觉时仍然要挨着墙），也学会了几句帝国话，说得不好，别人常常假装听懂。安置点给过你一份活：替矮人的石语行会探浅层的洞，靠听岩石的响判断哪里能挖。你那双耳朵是这一手本事唯一的原因，而矮人管这叫「山下人的耳朵」。你现在的处境是：同出来的人两年里死了十一个，多数是睡着之后不再醒来，剩下的人开始怀疑走出来是不是错的；而安置点那边正在统计「还有多少旧民活着」，这份名册将来会决定谁被算作「族」。',
          attributeBonus: { lore: 1, craft: 2 },
