          description: '两年前你替一个人作了保（矮人叫保人，联邦叫担保）。你保的金额是四百马克，相当于你四年的收入。你保的那个人没有跑——他死了，死在盐路上，货物被抢，尸首半年后才被人认出来。按规矩，保人的责任随被保人的死亡转移到了他的遗产上，而他的遗产只有一匹老马与两间破屋，值不到九十马克。于是剩下的三百多马克落在了你身上。债主很有礼貌，没有打你，只是每隔两个月来一次，坐下来喝茶，说一句「不急」，然后留下一个名字和日期。你现在的每一个决定背后都有三百马克。',
