          title: '你听过龙的一句话',
          description: '十四岁那年，你在白垩脊南麓的一个村子里替人看马。一个阴天的下午，你听到山谷里传来一串很长的声音，不是雷，也不是风，那声音让村里所有的狗同时不叫了。后来你才明白那大概是龙语，而你是村里唯一把它记下来的人——你不会说，但你记得那串声音的长短与高低，你能哼出来。这件事你只告诉过两个人，一个是村里的老人（他让你再也别提），一个是石桥市的一个精灵收购商（他给你倒了一杯水，然后问了你三个问题，然后把价格提到了「一年不必干活」的数目，你拒绝了，此后他开始每年派人来问你一次）。你至今不知道那句话是什么意思，但你知道有人愿意为它出很多钱。',
