          title: '有人在一封信里点了你的名字',
          description: '三个月前，你收到了一个不认识的人送来的一封信。信里没有称呼、没有署名，只有一句话与一个日期：「霜月十七日，白石城北门内的铁砧酒馆，凭此信入内。」信的最后一行写着你母亲的名字、你已经死去的师父的名字、以及一个你从没对人说过的、你小时候的绰号。你把信烧了，但你记得每一个字。你现在的处境是：日期还有十一天，你离白石城有九天路程，而你不知道去那里会发生什么——你只知道写这封信的人手上有你最要紧的三件事。这一趟不管去不去，你都得先弄明白：谁在数你的日子。',
          attributeBonus: { guile: 1, faith: 1, lore: 1 },
